steps_log.command:
jq 'def rename_prot_to_port:
  if type == "object" then
    reduce keys_unsorted[] as $k ({};
      if $k == "prot" then
        . + { "port": .[$k] }
      else
        . + { $k: rename_prot_to_port | .[$k] }
      end
    )
  elif type == "array" then
    map(rename_prot_to_port)
  else
    .
  end;
rename_prot_to_port' /tmp/ageval/config.json > /tmp/ageval/config.json.tmp && mv /tmp/ageval/config.json.tmp /tmp/ageval/config.json

